import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    os_type = platform.system()
    if os_type == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["top", "-bn1", "|", "grep", "%Cpu", "|", "awk", "'{print $8}'"]
    records = []
    iterations = int(duration // interval)
    for i in range(iterations):
        timestamp = time.time()
        try:
            if os_type == "Windows":
                output = subprocess.check_output(cmd, shell=True).decode().strip().split("\n")[1].strip()
                cpu_percent = float(output)
            else:
                output = subprocess.check_output(["top", "-bn1"], shell=True).decode()
                for line in output.split("\n"):
                    if "%Cpu" in line:
                        parts = line.split()
                        cpu_percent = float(parts[7])
                        break
        except:
            cpu_percent = 0.0
        records.append({"timestamp": timestamp, "cpu_percent": cpu_percent})
        if i < iterations - 1:
            time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

