import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    proc = subprocess.Popen(script_path, shell=True)
    try:
        ps_proc = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    deadline = start_time + timeout
    while True:
        if time.time() > deadline:
            proc.terminate()
            break
        try:
            cpu_usage += ps_proc.cpu_percent(interval=0.1)
            mem_info = ps_proc.memory_info()
            memory_usage += mem_info.rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        if not ps_proc.is_running():
            break
    proc.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

